sample:
# lesson02 ch02: リソース参照
# 「型.名前.属性」で他のリソースの値を使えます。

resource "terraform_data" "origin" {
  input = "origin-value"
}

output "from_resource" {
  # 参照を書いた時点で origin への依存関係が自動でできます
  value = terraform_data.origin.output
}

output "from_literal" {
  # こちらはただのリテラル。参照ではありません
  value = "origin-value"
}

exercise.starter:
# 参照は 型.名前.属性 の形
resource "terraform_data" "origin" {
}

exercise.answer:
# 参照は 型.名前.属性。ここでは terraform_data.origin.output です。
# 参照を書くと Terraform が「origin を先に作る」という依存関係を自動で組みます。
resource "terraform_data" "origin" {
  input = "参照元"
}

output "from_resource" {
  value = terraform_data.origin.output
}

output "ref_style" {
  value = "型.名前.属性"
}
